input.command:
sed -i 's/<code location>/${APP_CODE_LOCATION}/g; s/<spec location>/${APP_SPEC_LOCATION}/g' src/system_prompts.rs src/hidden_anchor.rs && python3 - <<'EOF'
p='src/system_prompts.rs'; s=open(p).read()
a='''//! [`crate::settings_window`]). In a template, `${APP_CODE_LOCATION}` and
//! `${APP_SPEC_LOCATION}` stand for `codeRoot` and `root` in `piton.config.pi`.
//! Like the prompt it is sent with, a template is Piton prose, so it can
//! reference the spec.'''
b='''//! [`crate::settings_window`]). In a template, `${APP_CODE_LOCATION}` and
//! `${APP_SPEC_LOCATION}` stand for `codeRoot` and `root` in `piton.config.pi`,
//! written like Piton interpolations and filled in before the prompt is
//! compiled. Otherwise, like the prompt it is sent with, a template is Piton
//! prose, so it can reference the spec.'''
assert s.count(a)==1; s=s.replace(a,b); open(p,'w').write(s)
EOF
grep -n "APP_" src/system_prompts.rs | head -8; cargo test 2>&1 | grep -E "^error|test result|FAILED" | head

